def apply_appointment(
    db: GameDB,
    state: GameState,
    content: GameContent,
    data: Optional[Dict[str, object]] = None,
    llm_config: Optional[LLMConfig] = None,
    commit: bool = True,
) -> Tuple[str, str]:
    """诏书任命共用落地：建档入库，本回合即可召见。"""
    if not data:
        return ("", "")
    if "approved" in data and not bool(data.get("approved")):
        return ("", "")
    name = str(data.get("name") or "").strip()
    office = str(data.get("office") or "").strip()
    if not name or not office:
        return ("", "")
    office = normalize_office(office)
    # 显式名分（office_type ∈ PERSON_TITLE_KINDS）在此建 Character 前就得保住：add_character 的
    # 名分守卫看的是 character.office_type，若这里先被 infer 反推成官职（office='诸生'→'生员'），
    # 守卫永远见不到名分、误建 offices/character_offices（#1059 codex l6h）。
    office_type = resolve_office_type_preserving_title(
        office,
        str(data.get("office_type") or "").strip(),
        "待铨",
        llm_config or db.llm_config,
    )
    if office_type == "后宫":
        return ("", "")

    # ── 查重：精确名 + aliases 命中即拒，不重复建档 ──────────
    # 身份归一认识未仕/宗藩——在册者（含史可法诸生）由此拒新建，走 apply_office_appointment。
    if name in content.characters:
        return ("", "")
    existing = _find_existing_minister(content, name, db)
    if existing is not None:
        return ("", "")

    # ── 职位替换：腾缺现任者 → dismissed ───────────────────────────
    displaced = ""
    replaces = str(data.get("replaces") or "").strip()
    if replaces and replaces in content.characters:
        old = content.characters[replaces]
        if old.status == "active":
            db.set_character_status(
                state, replaces, "dismissed",
                reason=f"{office}改授{name}，原任去职",
                content=content,
                commit=commit,
            )
            displaced = replaces

    person_fields = canonical_new_appointment_person_fields(
        content, data.get("faction"),
    )
    character = Character(
        name=name,
        office=office,
        office_type=office_type,
        aliases=[],
        personal_skills=[],
        power_id="ming",
        status="active",
        office_region=str(
            data.get("office_region") or data.get("region_id") or ""
        ).strip(),
        **person_fields,
    )
    content.characters[name] = character
    db.add_character(state, character, llm_config=llm_config, commit=commit)
    # add_character 已写入并分配 portrait_id，回写到内存对象
    row = db.conn.execute(
        "SELECT portrait_id FROM characters WHERE name=?", (name,)
    ).fetchone()
    if row:
        character.portrait_id = str(row["portrait_id"])
    return (name, displaced)

def stopped_covert_effect(
    db: Any, *, origin_ref: object, beyond_intent: object = False,
) -> bool:
    """True only for a post-prohibition covert leg owned by the targeted old dossier."""
    origin = str(origin_ref or "").strip()
    if not origin.startswith("dossier:"):
        return False
    raw_id = origin.removeprefix("dossier:")
    if not raw_id.isdigit():
        return False
    from ming_sim.simulation import read_beyond_intent_raw
    beyond = db.coerce_beyond_intent_flag(read_beyond_intent_raw({"beyond_intent": beyond_intent}))
    if not beyond:
        return False
    return active_prohibition_dossier(db, int(raw_id)) is not None

def _write_locations_in_source(source: str, relative: str) -> set[str]:
    """Scan one module's source for direct ``characters``-mutating execute() SQL.

    Handles both plain string literals AND f-strings (``ast.JoinedStr``): an
    f-string execute arg like ``f"DELETE FROM characters WHERE ..."`` is the
    Call arg as a whole, so it matches directly (its inner ``Constant`` parts
    have the JoinedStr as parent — not the Call — so they are correctly skipped
    by ``_is_sql_execute_argument``; before this an f-string-only write point
    escaped the inventory scan entirely)."""
    tree = ast.parse(source)
    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent
    found: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            sql_src = node.value
        elif isinstance(node, ast.JoinedStr):
            sql_src = "".join(
                v.value for v in node.values
                if isinstance(v, ast.Constant) and isinstance(v.value, str)
            )
        else:
            continue
        if not _is_sql_execute_argument(node, parents):
            continue
        sql = " ".join(sql_src.split())
        if not any(marker in sql for marker in _MUTATING_SQL_MARKERS):
            continue
        function_name = _enclosing_function_name(node, parents)
        found.add(_inventory_location(relative, function_name, sql))
    return found

def _loads_lenient(
    raw: str, *, accepted_types: tuple[type, ...] = (dict,),
) -> Optional[Any]:
    """容错解析 JSON：剥代码围栏并截取首个受理容器。失败返回 None。"""
    t = (raw or "").strip()
    if t.startswith("```"):
        t = re.sub(r"^```[a-zA-Z]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t).strip()
    starts = []
    if dict in accepted_types:
        starts.append((t.find("{"), "}"))
    if list in accepted_types:
        starts.append((t.find("["), "]"))
    starts = [(index, closer) for index, closer in starts if index >= 0]
    if not starts:
        return None
    i, closer = min(starts, key=lambda item: item[0])
    j = t.rfind(closer)
    if j <= i:
        return None
    body = t[i:j + 1]
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        # 严格解析失败才做 JSONC 容错（CMR F8）：模型照 prompt 模板回带 // 行注释或尾逗号时救回。
        # 先严格、失败才清洗 —— 合法 JSON 不经清洗器。清洗器 quote-aware：串值里的 //、,}、://
        # 一律不动（#6，旧裸正则会误伤 "x,}"→"x}"、"a//b"→截断）。
        try:
            obj = json.loads(_strip_jsonc(body))
        except (ValueError, TypeError):
            return None
    return obj if isinstance(obj, accepted_types) else None

def _normalize_dossier_report_origin(
    cls, origin: object, *, is_terminal: bool = False,
) -> str:
    raw = str(origin or "").strip()
    if not raw:
        return (
            cls.DOSSIER_REPORT_ORIGIN_VERDICT
            if is_terminal
            else cls.DOSSIER_REPORT_ORIGIN_MONTHLY
        )
    prefix = cls.DOSSIER_REPORT_ORIGIN_NS
    if not raw.startswith(prefix) or not raw[len(prefix):].strip():
        raise ValueError("奏报 origin 须带 dossier-report 命名空间前缀")
    return raw

def _promulgation_decision_raw(row: dict) -> str:
    """Resolve the current promulgation-slot raw enum for a dossier row."""
    verdict = str(row.get("settlement_verdict") or "").strip()
    if verdict in DOSSIER_DECISION_CN:
        return verdict
    decision = str(row.get("promulgation_decision") or "").strip()
    if decision in DOSSIER_DECISION_CN:
        return decision
    if bool(row.get("was_force_promulgated")):
        return "force_promulgated"
    stigma = row.get("stigma") or []
    if isinstance(stigma, list):
        for item in stigma:
            if not isinstance(item, dict) or item.get("kind") != "midzhi":
                continue
            source = str(item.get("source_action") or "").strip()
            if source == "force_promulgated":
                return "force_promulgated"
            if source == "promulgated":
                return "promulgated"
            if source == "rejected":
                return "rejected"
    return decision

def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
